/bin/bash -lc "node --input-type=module <<'NODE'
import { readFileSync, writeFileSync } from 'node:fs';

const manifest = JSON.parse(readFileSync('work/lib/package.json', 'utf8'));
const entry = new URL(manifest.exports, new URL('./work/lib/', import.meta.url));
const { readMinor, mulDivMinor } = await import(entry);
const rows = JSON.parse(readFileSync('work/rows.json', 'utf8'));

function toDto(minor) {
  return { unit: 'EUR-cent', value: readMinor(minor.toString()).toString() };
}

const settlement = rows.map(({ id, unitMinor, quantity }) => {
  if ("'!Number.isSafeInteger(quantity)) throw new Error(`Invalid quantity for ${id}`);
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, '"'half-away');
  const fee = mulDivMinor(net, 1n, 2n, 'half-away');
  return { id, net: toDto(net), fee: toDto(fee) };
});

writeFileSync('settlement.json', JSON.stringify(settlement, null, 2) + '\\n', { flag: 'wx' });
NODE"

/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { readMinor } from './work/lib/money.mjs';

const rows = JSON.parse(readFileSync('work/rows.json', 'utf8'));
const actual = JSON.parse(readFileSync('settlement.json', 'utf8'));
assert.deepEqual(actual.map(({ id }) => id), rows.map(({ id }) => id));

const expected = [
  { id: 'AR', net: '5', fee: '3' },
  { id: 'AV', net: '-5', fee: '-3' },
  { id: 'AZ', net: '9007199254740993', fee: '4503599627370497' },
];
for (const [index, row] of actual.entries()) {
  assert.equal(row.id, expected[index].id);
  for (const key of ['net', 'fee']) {
    const value = expected[index][key];
    assert.deepEqual(row[key], { unit: 'EUR-cent', value });
    assert.equal(readMinor(row[key].value).toString(), value);
  }
}
console.log('Verified all 3 rows against independent expected values and ENGINE-1 DTO parsing.');
NODE
cat settlement.json"

